// A class for demonstration
class Widget {};

// Calling a constructor with an argument is fine with ()
Widget w1(10);

// Most Vexing Parse: This declares a function, not an object!
// It declares a function named 'w2' that takes no arguments
// and returns a Widget.
Widget w2();

// Using braced initialization correctly creates a default-constructed object.
// This syntax is unambiguous to the parser.
Widget w3{};
